**Root cause.** `service.vulnerable.js` built the 12-byte GCM nonce from a counter cached in a `Map` keyed by `sha256(plaintext)`. The cached counter was read, written into the last 4 bytes of the nonce, and **re-stored without incrementing**. So encrypting the same payload twice resurrected the identical nonce under the same 256-bit key → identical CTR keystream → `ciphertext₁ ⊕ ciphertext₂ = plaintext₁ ⊕ plaintext₂`, and GCM's authenticity is void (verified below).

**Fix** (`service.js`): drop the plaintext-derived cache entirely and draw a fresh 12-byte nonce from the OS CSPRNG on every call — nothing keyed on the plaintext can resurrect an old nonce.

```js
'use strict';
const crypto = require('node:crypto');

const ALGORITHM = 'aes-256-gcm';
const NONCE_LENGTH = 12;          // 96-bit nonce (NIST-recommended for GCM)
const KEY = crypto.randomBytes(32); // production: KMS / secret store

function encrypt(plaintext) {
  // Fresh, cryptographically random nonce — unique per encryption call.
  const nonce = crypto.randomBytes(NONCE_LENGTH);
  const cipher = crypto.createCipheriv(ALGORITHM, KEY, nonce);
  const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = cipher.getAuthTag();
  return {
    nonce: nonce.toString('base64'),
    ciphertext: ciphertext.toString('base64'),
    tag: tag.toString('base64'),
  };
}

function decrypt(payload) {
  const nonce = Buffer.from(payload.nonce, 'base64');
  const ciphertext = Buffer.from(payload.ciphertext, 'base64');
  const tag = Buffer.from(payload.tag, 'base64');
  const decipher = crypto.createDecipheriv(ALGORITHM, KEY, nonce);
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
}

module.exports = { encrypt, decrypt, KEY, NONCE_LENGTH };
```

Collision risk is negligible: with random 96-bit nonces the birthday bound is ~2⁴⁸ encryptions per key (rotate the key well before that; standard GCM bounds). `test.js` adds the required regression test — identical plaintext encrypted twice must yield distinct nonces — plus 9 edge-case tests. Run with `npm test` (`node --test`).
